import java.io.*;

public class Demo {
    public static void main(String[] args) throws IOException {
        String name="Linh";
        int mark=85;
        try(PrintWriter out=new PrintWriter("marks.txt","UTF-8")) {
            out.println(name+","+mark);
        }
        // the reader's contract: one record per line, name then mark, separated by a comma
        String line;
        try(BufferedReader in=new BufferedReader(new FileReader("marks.txt"))) {
            line=in.readLine();
        }
        String[] fields=line.split(",");
        System.out.println("fields: "+fields.length);
        if(fields.length!=2) System.out.println("reader rejects: expected 2 fields, got "+fields.length);
        else if(!fields[1].matches("[0-9]+")) System.out.println("reader rejects: mark is not a number: "+fields[1]);
        else System.out.println("name="+fields[0]+" mark="+fields[1]);
    }
}

