        boolean special=value.contains(",")||value.contains("\"")||value.contains("\n")||value.contains("\r");
        if(!special) return value;
        return "\""+value.replace("\"","\"\"")+"\"";
    }
    public static void main(String[] args) {
        String[] names={"Linh","An, Mai","Bao \"Ben\" Tran"};
        int[] marks={85,72,90};
        System.out.println("name,mark");
        for(int i=0;i<names.length;i++) System.out.println(field(names[i])+","+marks[i]);
    }
}

